<?php
namespace App\Controllers;
use App\Core\Database;
final class AdminController{
 public function dashboard():void{$db=Database::db();$sales=(int)$db->query("SELECT COALESCE(SUM(total),0) FROM orders WHERE status='paid'")->fetchColumn();$orders=(int)$db->query("SELECT COUNT(*) FROM orders WHERE status='paid'")->fetchColumn();$stats=['sales'=>$sales,'orders'=>$orders,'pending'=>(int)$db->query("SELECT COUNT(*) FROM orders WHERE status='pending'")->fetchColumn(),'sold'=>(int)$db->query("SELECT COUNT(*) FROM order_items i JOIN orders o ON o.id=i.order_id WHERE o.status='paid'")->fetchColumn(),'photos'=>(int)$db->query('SELECT COUNT(*) FROM photos')->fetchColumn(),'storage'=>(int)$db->query('SELECT COALESCE(SUM(file_size),0) FROM photos')->fetchColumn(),'average'=>$orders?(int)round($sales/$orders):0];$daily=$db->query("SELECT DATE(paid_at) day,SUM(total) total FROM orders WHERE paid_at>=DATE_SUB(CURDATE(),INTERVAL 13 DAY) AND status='paid' GROUP BY DATE(paid_at) ORDER BY day")->fetchAll();$topEvents=$db->query("SELECT e.name,e.sport,e.event_date,COALESCE(SUM(i.unit_price),0) sales,COUNT(DISTINCT o.id) orders_count,MIN(p.id) photo_id,MIN(p.preview_path) preview_path FROM events e JOIN photos p ON p.event_id=e.id LEFT JOIN order_items i ON i.photo_id=p.id LEFT JOIN orders o ON o.id=i.order_id AND o.status='paid' GROUP BY e.id ORDER BY sales DESC LIMIT 3")->fetchAll();$recent=$db->query("SELECT o.*,COUNT(i.id) items FROM orders o LEFT JOIN order_items i ON i.order_id=o.id GROUP BY o.id ORDER BY o.id DESC LIMIT 6")->fetchAll();admin_view('admin/dashboard',['stats'=>$stats,'daily'=>$daily,'topEvents'=>$topEvents,'recent'=>$recent,'pageTitle'=>'Resumen','adminSection'=>'dashboard']);}
 public function photos():void{$db=Database::db();$events=$db->query('SELECT * FROM events ORDER BY event_date DESC')->fetchAll();$photos=$db->query('SELECT p.*,e.name event_name FROM photos p JOIN events e ON e.id=p.event_id ORDER BY p.id DESC LIMIT 100')->fetchAll();admin_view('admin/photos',['events'=>$events,'photos'=>$photos,'pageTitle'=>'Subir fotografías','adminSection'=>'photos']);}
 public function upload():never{verify_csrf();$event=(int)($_POST['event_id']??0);$watermark=isset($_POST['watermark']);$wmType=($_POST['watermark_type']??'text')==='image'?'image':'text';$wmText=trim($_POST['watermark_text']??'ULTRA MEDIA DIGITAL');$wmImage=null;if($watermark&&$wmType==='image'&&isset($_FILES['watermark_image'])&&$_FILES['watermark_image']['error']===UPLOAD_ERR_OK&&($_FILES['watermark_image']['tmp_name']))$wmImage=$_FILES['watermark_image']['tmp_name'];$files=$_FILES['photos']??null;if(!$event||!$files){$_SESSION['error']='Selecciona un evento y al menos una fotografía.';redirect('/admin/fotos');}$individual=isset($_POST['individual_enabled']);$setEnabled=isset($_POST['set_enabled']);$packEnabled=isset($_POST['pack_enabled']);$packQuantity=max(2,(int)($_POST['pack_quantity']??5));$packPrice=max(0,(int)($_POST['pack_price']??14990));if($packEnabled&&$packQuantity>count((array)($files['tmp_name']??[]))){$_SESSION['error']='La cantidad del pack no puede superar las fotografías cargadas.';redirect('/admin/fotos');}if(!$individual&&!$setEnabled&&!$packEnabled){$_SESSION['error']='Habilita la venta individual, el set completo o el pack de fotografías.';redirect('/admin/fotos');}$setName=trim($_POST['set_name']??'');if($setName==='')$setName='Set '.date('d-m-Y H:i');$db=Database::db();$set=$db->prepare("INSERT INTO photo_sets(event_id,name,bib_number,individual_enabled,set_enabled,pack_enabled,pack_quantity,pack_price,set_price) VALUES(?,?,?,?,?,?,?,?,?)");$set->execute([$event,$setName,trim($_POST['bib_number']??''),$individual?1:0,$setEnabled?1:0,$packEnabled?1:0,$packQuantity,$packPrice,max(0,(int)($_POST['set_price']??19990))]);$setId=(int)$db->lastInsertId();$dirs=[ROOT.'/storage/originals',ROOT.'/storage/previews'];foreach($dirs as $dir){if(!is_dir($dir)&&!@mkdir($dir,0775,true)){$_SESSION['error']='No fue posible crear la carpeta: '.$dir;redirect('/admin/fotos');}@chmod($dir,0775);if(!is_writable($dir)){$_SESSION['error']='La carpeta storage no tiene permisos de escritura.';redirect('/admin/fotos');}}$uploaded=0;$failed=[];foreach($files['tmp_name'] as $k=>$tmp){$name=$files['name'][$k]??'archivo';if(($files['error'][$k]??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK){$failed[]=$name.' (error de carga)';continue;}if(!is_uploaded_file($tmp)||!@getimagesize($tmp)){$failed[]=$name.' (imagen inválida)';continue;}$ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));if(!in_array($ext,['jpg','jpeg','png','webp'],true)){$failed[]=$name.' (formato no permitido)';continue;}$token=bin2hex(random_bytes(10));$orig='storage/originals/'.$token.'.'.$ext;$preview='storage/previews/'.$token.'.jpg';$origAbs=ROOT.'/'.$orig;$previewAbs=ROOT.'/'.$preview;if(!@move_uploaded_file($tmp,$origAbs)||!is_file($origAbs)){$failed[]=$name.' (sin permiso para guardar)';continue;}if(!$this->preview($origAbs,$previewAbs,$watermark,$wmText,$wmImage)){@unlink($origAbs);$failed[]=$name.' (no se pudo generar la vista previa)';continue;}$size=(int)@filesize($origAbs);$s=Database::db()->prepare("INSERT INTO photos(event_id,set_id,title,bib_number,price,original_path,preview_path,file_size,watermark_enabled,watermark_type,watermark_text,download_enabled,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?, 'active')");$s->execute([$event,$setId,pathinfo($name,PATHINFO_FILENAME),trim($_POST['bib_number']??''),max(0,(int)($_POST['price']??4990)),$orig,$preview,$size,$watermark?1:0,$wmType,$wmText,isset($_POST['download_enabled'])?1:0]);$uploaded++;}if($uploaded)$_SESSION['success']=$uploaded.' fotografía(s) publicada(s) correctamente.';if($failed)$_SESSION['error']='No se procesaron: '.implode(', ',$failed);redirect('/admin/fotos');}
 public function toggleDownload():never{verify_csrf();[$id,$enabled]=array_pad(explode(':',$_POST['toggle']??'0:0'),2,0);$s=Database::db()->prepare('UPDATE photos SET download_enabled=? WHERE id=?');$s->execute([(int)$enabled,(int)$id]);redirect('/admin/fotos');}
 public function editPhoto():void{$db=Database::db();$s=$db->prepare('SELECT p.*,e.name event_name,COALESCE(ps.pack_enabled,0) pack_enabled,ps.pack_quantity,ps.pack_price FROM photos p JOIN events e ON e.id=p.event_id LEFT JOIN photo_sets ps ON ps.id=p.set_id WHERE p.id=?');$s->execute([(int)($_GET['id']??0)]);$photo=$s->fetch();if(!$photo){http_response_code(404);exit('Fotografía no encontrada');}$events=$db->query('SELECT * FROM events ORDER BY event_date DESC')->fetchAll();admin_view('admin/photo-edit',['photo'=>$photo,'events'=>$events,'pageTitle'=>'Editar fotografía','adminSection'=>'photos']);}
 public function updatePhoto():never{verify_csrf();$db=Database::db();$id=(int)($_POST['id']??0);$find=$db->prepare('SELECT * FROM photos WHERE id=?');$find->execute([$id]);$photo=$find->fetch();if(!$photo){$_SESSION['error']='Fotografía no encontrada.';redirect('/admin/fotos');}$status=in_array($_POST['status']??'',['active','hidden'],true)?$_POST['status']:'active';$watermark=isset($_POST['watermark_enabled']);$wmType=($_POST['watermark_type']??'text')==='image'?'image':'text';$wmText=trim($_POST['watermark_text']??'ULTRA MEDIA DIGITAL');$wmLogo=null;if($watermark&&$wmType==='image'&&isset($_FILES['watermark_image'])&&($_FILES['watermark_image']['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_OK&&@getimagesize($_FILES['watermark_image']['tmp_name']))$wmLogo=$_FILES['watermark_image']['tmp_name'];if($watermark&&$wmType==='image'&&!$wmLogo){$_SESSION['error']='Selecciona nuevamente la imagen que usarás como marca de agua.';redirect('/admin/fotos/editar?id='.$id);}$original=$photo['original_path'];$preview=$photo['preview_path'];$size=(int)$photo['file_size'];$new=$_FILES['photo']??null;if($new&&($new['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){if($new['error']!==UPLOAD_ERR_OK||!is_uploaded_file($new['tmp_name'])||!@getimagesize($new['tmp_name'])){$_SESSION['error']='El archivo de reemplazo no es una imagen válida.';redirect('/admin/fotos/editar?id='.$id);}$ext=strtolower(pathinfo($new['name'],PATHINFO_EXTENSION));if(!in_array($ext,['jpg','jpeg','png','webp'],true)){$_SESSION['error']='El formato de reemplazo no está permitido.';redirect('/admin/fotos/editar?id='.$id);}$token=bin2hex(random_bytes(10));$newOriginal='storage/originals/'.$token.'.'.$ext;$newPreview='storage/previews/'.$token.'.jpg';if(!@move_uploaded_file($new['tmp_name'],ROOT.'/'.$newOriginal)||!$this->preview(ROOT.'/'.$newOriginal,ROOT.'/'.$newPreview,$watermark,$wmText,$wmLogo)){@unlink(ROOT.'/'.$newOriginal);$_SESSION['error']='No fue posible guardar o procesar la nueva imagen.';redirect('/admin/fotos/editar?id='.$id);}$oldOriginal=ROOT.'/'.ltrim($original,'/');$oldPreview=ROOT.'/'.ltrim($preview,'/');$original=$newOriginal;$preview=$newPreview;$size=(int)@filesize(ROOT.'/'.$newOriginal);if(is_file($oldOriginal))@unlink($oldOriginal);if(is_file($oldPreview))@unlink($oldPreview);}else{if(!$this->preview(ROOT.'/'.ltrim($original,'/'),ROOT.'/'.ltrim($preview,'/'),$watermark,$wmText,$wmLogo)){$_SESSION['error']='No fue posible regenerar la vista previa protegida.';redirect('/admin/fotos/editar?id='.$id);}}$s=$db->prepare('UPDATE photos SET event_id=?,title=?,bib_number=?,price=?,original_path=?,preview_path=?,file_size=?,watermark_enabled=?,watermark_type=?,watermark_text=?,download_enabled=?,status=? WHERE id=?');$s->execute([(int)$_POST['event_id'],trim($_POST['title']??''),trim($_POST['bib_number']??''),max(0,(int)$_POST['price']),$original,$preview,$size,$watermark?1:0,$wmType,$wmText,isset($_POST['download_enabled'])?1:0,$status,$id]);if(!empty($photo['set_id'])){$packEnabled=isset($_POST['pack_enabled']);$packQuantity=max(2,(int)($_POST['pack_quantity']??5));$packPrice=max(0,(int)($_POST['pack_price']??14990));$db->prepare('UPDATE photo_sets SET pack_enabled=?,pack_quantity=?,pack_price=? WHERE id=?')->execute([$packEnabled?1:0,$packQuantity,$packPrice,(int)$photo['set_id']]);}$_SESSION['success']='Fotografía actualizada correctamente.';redirect('/admin/fotos');}
 public function togglePhotoStatus():never{verify_csrf();$status=($_POST['status']??'')==='active'?'active':'hidden';Database::db()->prepare('UPDATE photos SET status=? WHERE id=?')->execute([$status,(int)$_POST['id']]);$_SESSION['success']=$status==='active'?'Fotografía habilitada.':'Fotografía deshabilitada.';redirect('/admin/fotos');}
 public function deletePhoto():never{verify_csrf();$db=Database::db();$id=(int)$_POST['id'];$sold=$db->prepare('SELECT COUNT(*) FROM order_items WHERE photo_id=?');$sold->execute([$id]);if((int)$sold->fetchColumn()>0){$db->prepare("UPDATE photos SET status='hidden' WHERE id=?")->execute([$id]);$_SESSION['success']='La fotografía posee ventas asociadas y fue deshabilitada para conservar el historial.';redirect('/admin/fotos');}$s=$db->prepare('SELECT original_path,preview_path FROM photos WHERE id=?');$s->execute([$id]);$photo=$s->fetch();if($photo){foreach(['original_path','preview_path'] as $key){$candidate=ROOT.'/'.ltrim($photo[$key],'/');$storage=realpath(ROOT.'/storage');$parent=realpath(dirname($candidate));if($storage&&$parent&&str_starts_with($parent,$storage)&&is_file($candidate))unlink($candidate);}$db->prepare('DELETE FROM photos WHERE id=?')->execute([$id]);$_SESSION['success']='Fotografía eliminada definitivamente.';}redirect('/admin/fotos');}
 private function preview(string $src,string $dest,bool $wm,string $text='ULTRA MEDIA DIGITAL',?string $logoPath=null):bool{$info=@getimagesize($src);if(!$info||!function_exists('imagecreatetruecolor'))return false;$create=match($info[2]){IMAGETYPE_JPEG=>'imagecreatefromjpeg',IMAGETYPE_PNG=>'imagecreatefrompng',IMAGETYPE_WEBP=>'imagecreatefromwebp',default=>null};if(!$create||!function_exists($create))return false;$im=@$create($src);if(!$im)return false;$w=imagesx($im);$h=imagesy($im);if($w<1||$h<1){imagedestroy($im);return false;}$nw=min($w,1600);$nh=max(1,(int)round($h*$nw/$w));$out=imagecreatetruecolor($nw,$nh);$bg=imagecolorallocate($out,255,255,255);imagefill($out,0,0,$bg);imagecopyresampled($out,$im,0,0,0,0,$nw,$nh,$w,$h);if($wm&&$logoPath){$li=@getimagesize($logoPath);$loader=$li?match($li[2]){IMAGETYPE_JPEG=>'imagecreatefromjpeg',IMAGETYPE_PNG=>'imagecreatefrompng',IMAGETYPE_WEBP=>'imagecreatefromwebp',default=>null}:null;$logo=$loader&&function_exists($loader)?@$loader($logoPath):false;if($logo){$lw=imagesx($logo);$lh=imagesy($logo);$targetW=max(120,(int)($nw*.38));$targetH=max(1,(int)($lh*$targetW/$lw));$scaled=imagecreatetruecolor($targetW,$targetH);imagesavealpha($scaled,true);imagefill($scaled,0,0,imagecolorallocatealpha($scaled,0,0,0,127));imagecopyresampled($scaled,$logo,0,0,0,0,$targetW,$targetH,$lw,$lh);imagecopy($out,$scaled,(int)(($nw-$targetW)/2),(int)(($nh-$targetH)/2),0,0,$targetW,$targetH);imagedestroy($scaled);imagedestroy($logo);}}elseif($wm){$label=$text!==''?$text:'ULTRA MEDIA DIGITAL';$white=imagecolorallocatealpha($out,255,255,255,55);for($y=100;$y<$nh;$y+=220)for($x=20;$x<$nw;$x+=360)imagestring($out,5,$x,$y,$label,$white);}$saved=@imagejpeg($out,$dest,78);imagedestroy($im);imagedestroy($out);return $saved&&is_file($dest);}
}
